using System.IO;
using System.Security.Cryptography;
namespace CremaTools;

public record RenameRow(string Source, string Destination) { public string Ancien => Path.GetFileName(Source); public string Nouveau => Path.GetFileName(Destination); public string Dossier => Path.GetDirectoryName(Destination)!; }
public class MoveRecord { public string Source { get; set; } = ""; public string Destination { get; set; } = ""; public string Temporary { get; set; } = ""; public string Hash { get; set; } = ""; public int Stage { get; set; } }
public class RenameJournal { public List<MoveRecord> Files { get; set; } = []; public bool Complete { get; set; } }
public static class RenameEngine
{
    public static List<RenameRow> Plan(IEnumerable<string> files, string pattern, int start, int digits, string target, string classify) { int n = start; return files.Select(file => { var info = new FileInfo(file); string name = pattern.Replace("{nom}", Path.GetFileNameWithoutExtension(file)).Replace("{n}", (n++).ToString(new string('0', digits))).Replace("{date}", info.LastWriteTime.ToString("yyyy-MM-dd")); name = Storage.Clean(name) + info.Extension; string folder = string.IsNullOrEmpty(target) ? info.DirectoryName! : target; if (classify == "Par type de fichier") folder = Path.Combine(folder, string.IsNullOrEmpty(info.Extension) ? "Sans extension" : info.Extension[1..].ToUpperInvariant()); if (classify == "Par année") folder = Path.Combine(folder, info.LastWriteTime.Year.ToString()); return new RenameRow(info.FullName, Path.GetFullPath(Path.Combine(folder, name))); }).ToList(); }
    static string Hash(string file) { using var input = File.OpenRead(file); return Convert.ToHexString(SHA256.HashData(input)); }
    public static void Validate(List<RenameRow> rows) { if (rows.Count == 0) throw new Exception("Ajoutez des fichiers."); if (rows.Select(r => r.Destination).Distinct(StringComparer.OrdinalIgnoreCase).Count() != rows.Count) throw new Exception("Plusieurs fichiers auraient le même nom. Ajoutez {n} au modèle."); var sources = rows.Select(r => r.Source).ToHashSet(StringComparer.OrdinalIgnoreCase); foreach (var row in rows) { if (!File.Exists(row.Source)) throw new Exception("Fichier introuvable : " + row.Source); if (Directory.Exists(row.Destination) || (File.Exists(row.Destination) && !sources.Contains(row.Destination))) throw new Exception("Ce nom existe déjà : " + row.Destination); } }
    public static void Apply(List<RenameRow> rows, string journalFile) { Validate(rows); var journal = new RenameJournal { Files = rows.Where(r => !string.Equals(r.Source, r.Destination, StringComparison.Ordinal)).Select(r => new MoveRecord { Source = r.Source, Destination = r.Destination, Temporary = Path.Combine(Path.GetDirectoryName(r.Source)!, ".crematools-" + Guid.NewGuid().ToString("N")), Hash = Hash(r.Source) }).ToList() }; if (journal.Files.Count == 0) return; Storage.Write(journalFile, journal); try { foreach (var file in journal.Files) { File.Move(file.Source, file.Temporary); file.Stage = 1; Storage.Write(journalFile, journal); } foreach (var file in journal.Files) { Directory.CreateDirectory(Path.GetDirectoryName(file.Destination)!); File.Move(file.Temporary, file.Destination); file.Stage = 2; Storage.Write(journalFile, journal); } journal.Complete = true; Storage.Write(journalFile, journal); } catch { try { Recover(journalFile); } catch { } throw; } }
    public static void Recover(string journalFile)
    {
        var journal = Storage.Read(journalFile, new RenameJournal()); foreach (var f in journal.Files) { if (File.Exists(f.Temporary)) f.Stage = 1; else if (f.Stage > 0 && File.Exists(f.Destination)) f.Stage = 2; else if (f.Stage <= 1 && File.Exists(f.Source)) f.Stage = 0; else if (f.Stage > 0) throw new Exception("Un fichier du classement est introuvable. Vérifiez le journal avant de continuer : " + f.Source); }
        var active = journal.Files.Where(f => f.Stage > 0).ToList(); foreach (var f in active) { string location = f.Stage == 2 ? f.Destination : f.Temporary; if (!File.Exists(location) || Hash(location) != f.Hash) throw new Exception("Un fichier a changé depuis le classement. Annulation interrompue pour préserver vos fichiers : " + location); if (File.Exists(f.Source) && !active.Any(a => a.Stage == 2 && string.Equals(a.Destination, f.Source, StringComparison.OrdinalIgnoreCase))) throw new Exception("Le nom d’origine est occupé : " + f.Source); }
        foreach (var f in active.Where(f => f.Stage == 2)) { File.Move(f.Destination, f.Temporary); f.Stage = 1; Storage.Write(journalFile, journal); }
        foreach (var f in active) { File.Move(f.Temporary, f.Source); f.Stage = 0; Storage.Write(journalFile, journal); }
        journal.Complete = false; Storage.Write(journalFile, journal);
    }
}
